import pandas as pd
import numpy as np

def clean(df):
    def parse_price(s):
        s = s.strip()
        if s.startswith('$'):
            s = s[1:]
        try:
            return float(s)
        except:
            return np.nan
    df['Price'] = df['Price'].apply(parse_price)
    df = df.dropna(subset=['Price'])
    df = df[(df['Quantity'].astype(int) == df['Quantity']) & (df['Quantity'] >= 1)]
    allowed_regions = ['North', 'South', 'East', 'West']
    df['Region'] = df['Region'].apply(lambda x: x.strip().title() if x is not None else np.nan)
    df = df.replace({'Region': np.nan}, subset=['Region'])
    df = df[df['Region'].isin(allowed_regions)]
    return df

